#!/bin/sh
# Shared hook Python runner: picks the first that actually runs of python3 > python > py -3 and passes arguments through (#987)
# Windows python3 may be the Store stub (prints Python, exits 49) > confirm with -c before picking
# No usable Python > exit 0 quietly (a hook failure must not block every tool call)
# POSIX sh only (works on macOS bash 3.2 and Git Bash). The extras copy is generated by scripts/sync_extras.py
for candidate in python3 python; do
  candidate_path=$(command -v "$candidate" 2>/dev/null) || continue
  # Attach /dev/null so the probe run does not consume the hook's stdin (JSON)
  if "$candidate_path" -c "import sys; sys.exit(0)" </dev/null >/dev/null 2>&1; then
    exec "$candidate_path" "$@"
  fi
done
# Windows Python launcher (py.exe): when a WindowsApps stub earlier on PATH makes both of the above stubs
launcher_path=$(command -v py 2>/dev/null) || exit 0
if "$launcher_path" -3 -c "import sys; sys.exit(0)" </dev/null >/dev/null 2>&1; then
  exec "$launcher_path" -3 "$@"
fi
exit 0
